package model

import "time"

// MaxSlotQty is the highest count a slot can be given, whatever its capacity.
// It is the width of the column, not a business rule: the real limit is the
// slot's own capacity, checked against the machine (TC-14).
const MaxSlotQty = 255

// MaxNoteRunes is how long an operator's note on a visit may be.
const MaxNoteRunes = 255

// RestockSession is one operator's visit to one machine (FR-15).
//
// ClientID is generated by the kiosk before it asks, which is what makes a
// resend safe: a visit saved twice would double-count what was loaded. StartedAt
// is the start of the operator's session, so the record says how long the visit
// took rather than only when it was filed.
type RestockSession struct {
	ID         int64
	ClientID   string
	MachineID  int64
	UserID     int64
	StartedAt  time.Time
	FinishedAt time.Time
	Note       string
}

// RestockItem is one slot's line in a visit: what it held, how many were in it
// before, and how many after. It is the evidence behind every count in the
// system, so it is written for every slot of the machine, not only the ones the
// operator touched.
type RestockItem struct {
	SlotID    int64
	ProductID *int64
	QtyBefore int
	QtyAfter  int
	// ProductChanged is true when this visit applied a planned product change,
	// which is why a count can rise without anything being added (FR-16).
	ProductChanged bool
}

// RestockSaved is the answer to a saved visit: what the kiosk needs to confirm
// it and to reload its screen at the right version.
type RestockSaved struct {
	ClientID       string
	SessionID      int64
	SavedAt        time.Time
	CatalogVersion int64
}

// MachineSlots is one machine with its slots, as the restock screen shows them
// (FR-14).
type MachineSlots struct {
	Machine Machine
	Slots   []Slot
}

// Visit is one operator visit as the admin's operator list refers to it: when,
// and to which machine.
type Visit struct {
	At          time.Time
	MachineCode string
}

// RestockFilter is one page of the restock history (UC-10, FR-25). Start and
// End are UTC instants, half-open, and they bound StartedAt: a visit belongs to
// the day the operator opened the machine. A zero MachineID or UserID means
// "don't filter on it".
type RestockFilter struct {
	Start, End        time.Time
	MachineID, UserID int64
	Limit, Offset     int
}

// RestockVisitItem is one slot's line of a visit as the history shows it, with
// the product named. ProductID and ProductName are nil for a slot that held
// nothing.
type RestockVisitItem struct {
	SlotNumber     int
	ProductID      *int64
	ProductName    *string
	QtyBefore      int
	QtyAfter       int
	ProductChanged bool
}

// RestockVisit is one visit as the admin history shows it, with the machine and
// the operator flattened in. Note is nil when the operator left it empty.
//
// ItemsAdded and SlotsChanged are counted from Items by Tally rather than
// stored: they are a reading of the evidence, and the evidence is the lines.
type RestockVisit struct {
	ID                             int64
	ClientID                       string
	StartedAt, FinishedAt          time.Time
	Note                           *string
	MachineID                      int64
	MachineCode, MachineName       string
	OperatorID                     int64
	OperatorName, OperatorUsername string
	ItemsAdded, SlotsChanged       int
	Items                          []RestockVisitItem
}

// RestockHistory is one page of the restock history. Page and PageSize are
// echoed back for the screen and filled in by the usecase, not the repository.
type RestockHistory struct {
	Total          int64
	Page, PageSize int
	Rows           []RestockVisit
}

// Tally counts what a visit changed: how many items were put in, and how many
// slots ended up different from how they started.
//
// A planned product change counts the whole new count as added (FR-16). That is
// not an approximation: applying a change empties the coil and refills it, so
// every item in it afterwards was put there at this visit, even when the count
// went down.
func Tally(items []RestockVisitItem) (added, slotsChanged int) {
	for _, it := range items {
		switch {
		case it.ProductChanged:
			added += it.QtyAfter
		case it.QtyAfter > it.QtyBefore:
			added += it.QtyAfter - it.QtyBefore
		}
		if it.ProductChanged || it.QtyAfter != it.QtyBefore {
			slotsChanged++
		}
	}
	return added, slotsChanged
}
